import os
import psycopg2
from flask import Flask, request, jsonify, g
import hashlib
import time

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, database=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def sanitize_order(order_val):
    """Allow only asc/desc for ORDER BY direction"""
    if order_val and order_val.lower() in ('asc', 'desc'):
        return order_val.lower()
    return 'asc'

def validate_api_key(key):
    """Timing-safe comparison for API key validation"""
    expected = os.environ.get('API_KEY', '')
    if len(key) != len(expected):
        return False
    result = 0
    for a, b in zip(key.encode(), expected.encode()):
        result |= a ^ b
    return result == 0

@app.before_request
def check_auth():
    api_key = request.headers.get('X-API-Key', '')
    if not validate_api_key(api_key):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/api/v2/reports/generate', methods=['POST'])
def generate_report():
    """Generate a filtered report based on user-specified criteria"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request'}), 400

    report_type = data.get('type', 'summary')
    filters = data.get('filters', {})
    sort_col = data.get('sort_by', 'created_at')
    sort_dir = sanitize_order(data.get('sort_dir', 'desc'))
    limit = min(int(data.get('limit', 50)), 500)

    # Build base query based on report type
    if report_type == 'transactions':
        base_query = "SELECT id, user_id, amount, status, created_at FROM transactions"
    elif report_type == 'audit_log':
        base_query = "SELECT id, actor, action, target, ts FROM audit_log"
    else:
        base_query = "SELECT id, name, email, department, created_at FROM users"

    # Apply dynamic column filter - sort_col is validated against allowed columns
    allowed_columns = {
        'transactions': ['id', 'user_id', 'amount', 'status', 'created_at'],
        'audit_log': ['id', 'actor', 'action', 'target', 'ts'],
        'summary': ['id', 'name', 'email', 'department', 'created_at']
    }

    if sort_col not in allowed_columns.get(report_type, []):
        sort_col = allowed_columns.get(report_type, ['id'])[0]

    # Build WHERE clause from filters
    where_clauses = []
    params = []
    for key, value in filters.items():
        if key in allowed_columns.get(report_type, []):
            # Use parameterized query for filter values
            where_clauses.append(f"{key} = %s")
            params.append(value)

    # Handle date range filter with custom expression
    date_range = data.get('date_range', '')
    if date_range:
        # Developer note: date_range is a pre-validated expression from frontend
        # Expected format: "created_at BETWEEN '2024-01-01' AND '2024-12-31'"
        where_clauses.append(date_range)

    if where_clauses:
        base_query += " WHERE " + " AND ".join(where_clauses)

    base_query += f" ORDER BY {sort_col} {sort_dir} LIMIT {limit}"

    try:
        db = get_db()
        cur = db.cursor()
        cur.execute(base_query, params)
        rows = cur.fetchall()
        columns = [desc[0] for desc in cur.description]
        results = [dict(zip(columns, row)) for row in rows]
        cur.close()
        return jsonify({'data': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v2/reports/export', methods=['POST'])
def export_report():
    """Export report as CSV - delegates to generate_report logic"""
    # Reuses same query building - included for completeness
    return jsonify({'status': 'queued', 'job_id': hashlib.md5(str(time.time()).encode()).hexdigest()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
